import{_ as a,o as e,c as r,a5 as i}from"./chunks/framework.a5no_H3L.js";const m=JSON.parse('{"title":".NET JIT 与 AOT：IL 如何变成机器码","description":"本页回答三个问题：JIT 如何把 IL 编译为机器码，分层编译与 PGO 如何平衡启动与峰值性能，AOT 带来什么收益和代价。编译流程见编译与 CLR。","frontmatter":{"type":"explanation","level":"intermediate"},"headers":[],"relativePath":"csharp/02-dotnet-runtime/chapter-04-jit-aot.md","filePath":"csharp/02-dotnet-runtime/chapter-04-jit-aot.md"}'),d={name:"csharp/02-dotnet-runtime/chapter-04-jit-aot.md"};function c(n,t,l,s,o,p){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="net-jit-与-aot-il-如何变成机器码" tabindex="-1" data-src-line="2" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">.NET JIT 与 AOT：IL 如何变成机器码 <a class="header-anchor" href="#net-jit-与-aot-il-如何变成机器码" aria-label="Permalink to &quot;.NET JIT 与 AOT：IL 如何变成机器码&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">本页回答三个问题：JIT 如何把 IL 编译为机器码，分层编译与 PGO 如何平衡启动与峰值性能，AOT 带来什么收益和代价。编译流程见<a href="./chapter-01-compilation-clr.html">编译与 CLR</a>。</p><h2 id="_1-jit-编译" tabindex="-1" data-src-line="6" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">1. JIT 编译 <a class="header-anchor" href="#_1-jit-编译" aria-label="Permalink to &quot;1. JIT 编译&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">IL 不是机器码，运行时需要把它翻译为当前 CPU 可执行的指令。JIT（Just-In-Time）编译器在方法第一次被调用时才编译该方法：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>IL → JIT（RyuJIT）→ 机器码 → CPU 执行</span></span></code></pre></div><p data-src-line="14" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">首次调用一个方法时，会有编译开销。方法一旦编译，后续调用直接执行机器码。这带来两个特点：</p><ul data-src-line="16" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><li data-src-line="16" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><strong>启动时</strong>：尚未被调用的方法不编译，启动快。</li><li data-src-line="17" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><strong>运行时</strong>：JIT 可以根据实际运行情况（目标 CPU 特性、运行时 profile）优化。</li></ul><p data-src-line="19" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">JIT 只知道目标平台是运行时所在的机器，因此能利用该 CPU 的特定指令集。</p><h2 id="_2-分层编译" tabindex="-1" data-src-line="21" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">2. 分层编译 <a class="header-anchor" href="#_2-分层编译" aria-label="Permalink to &quot;2. 分层编译&quot;">​</a></h2><p data-src-line="23" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">编译有优化成本：高度优化的代码编译慢，会拖慢启动。分层编译（tiered compilation）把编译分为两个阶段：</p><ol data-src-line="25" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><li data-src-line="25" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><strong>Tier 0</strong>：快速编译，几乎不优化，尽快让方法可执行。</li><li data-src-line="26" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><strong>Tier 1</strong>：方法被频繁调用后，重新编译为高度优化的版本。</li></ol><p data-src-line="28" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">冷路径方法停留在 Tier 0，热路径方法升级到 Tier 1。这样启动时不为冷代码支付优化成本，运行时又让热代码享受优化。升级是自动的，基于调用次数。</p><h2 id="_3-动态-pgo" tabindex="-1" data-src-line="30" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">3. 动态 PGO <a class="header-anchor" href="#_3-动态-pgo" aria-label="Permalink to &quot;3. 动态 PGO&quot;">​</a></h2><p data-src-line="32" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">动态 PGO（Profile-guided optimization，.NET 7 起）在 Tier 0 阶段插桩收集运行时信息——哪些分支更常走、哪些虚方法调用实际是哪个类型——再用这些信息指导 Tier 1 的优化。</p><p data-src-line="34" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">这使 JIT 能做出基于真实数据的优化，例如对常见的接口调用做去虚拟化（devirtualization）。动态 PGO 无需开发者手动提供 profile，运行时自己收集。</p><h2 id="_4-aot-编译" tabindex="-1" data-src-line="36" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">4. AOT 编译 <a class="header-anchor" href="#_4-aot-编译" aria-label="Permalink to &quot;4. AOT 编译&quot;">​</a></h2><p data-src-line="38" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">AOT（Ahead-Of-Time）在发布时把 IL 预编译为原生代码，运行时不再 JIT。.NET 提供两条路径：</p><ul data-src-line="40" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><li data-src-line="40" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><p data-src-line="40" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><strong>ReadyToRun（R2R）</strong>：把部分方法预编译为原生代码打进程序集，未预编译的方法仍回退 JIT。它改善启动，但保留 JIT 的动态能力。</p></li><li data-src-line="41" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><p data-src-line="41" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><strong>NativeAOT</strong>：完整预编译为单个原生可执行文件，运行时无 JIT。启动快、内存占用小、产物可自包含，但代价是：</p><ul data-src-line="43" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><li data-src-line="43" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">失去 JIT 的运行时动态优化能力，峰值吞吐可能低于 JIT。</li><li data-src-line="44" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">反射、动态加载等依赖 JIT 元数据的能力受限，需要额外配置。</li><li data-src-line="45" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">泛型的每个封闭类型都要在编译期生成，产物可能增大。</li></ul></li></ul><p data-src-line="47" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">AOT 适合启动敏感、内存受限或需要无依赖部署的场景（CLI 工具、微服务、无服务器）。长期运行、追求峰值吞吐的服务端程序通常仍用 JIT。</p><h2 id="_5-如何选择" tabindex="-1" data-src-line="49" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">5. 如何选择 <a class="header-anchor" href="#_5-如何选择" aria-label="Permalink to &quot;5. 如何选择&quot;">​</a></h2><table tabindex="0"><thead data-src-line="51" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><tr data-src-line="51" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><th style="text-align:left;">目标</th><th style="text-align:left;">建议</th></tr></thead><tbody data-src-line="53" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><tr data-src-line="53" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><td style="text-align:left;">长期运行的服务，追求峰值吞吐</td><td style="text-align:left;">JIT（默认）</td></tr><tr data-src-line="54" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><td style="text-align:left;">启动时间敏感的 CLI 工具</td><td style="text-align:left;">NativeAOT 或 R2R</td></tr><tr data-src-line="55" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><td style="text-align:left;">内存受限、无服务器</td><td style="text-align:left;">NativeAOT</td></tr><tr data-src-line="56" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><td style="text-align:left;">需要大量反射/动态加载</td><td style="text-align:left;">JIT（默认）</td></tr></tbody></table><p data-src-line="58" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">选择 AOT 不是「更快」的通用答案，而是在启动、内存、峰值性能和动态能力之间权衡。先用默认的 JIT，确认启动或内存是真实瓶颈后，再评估 AOT。</p><h2 id="_6-后续阅读" tabindex="-1" data-src-line="60" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">6. 后续阅读 <a class="header-anchor" href="#_6-后续阅读" aria-label="Permalink to &quot;6. 后续阅读&quot;">​</a></h2><ul data-src-line="62" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><li data-src-line="62" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><a href="./chapter-01-compilation-clr.html">编译与 CLR</a>解释 IL 与程序集。</li><li data-src-line="63" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><a href="./chapter-03-gc.html">GC</a>解释运行时的内存回收。</li><li data-src-line="64" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><a href="./chapter-05-unmanaged-interop.html">非托管互操作</a>解释原生边界与 AOT 的关系。</li><li data-src-line="65" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><a href="./../07-diagnostics/">诊断</a>了解如何测量启动与吞吐。</li></ul><blockquote data-src-line="67" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md"><p data-src-line="67" data-src-file="csharp/02-dotnet-runtime/chapter-04-jit-aot.md">本页的技术边界按 .NET 10 / C# 14 核对；分层编译自 .NET Core 3.0 起默认启用，动态 PGO 自 .NET 7 引入，NativeAOT 自 .NET 7 起可用。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/" target="_blank" rel="noreferrer">.NET 文档</a>、<a href="https://learn.microsoft.com/en-us/dotnet/core/deploying/native-aot/" target="_blank" rel="noreferrer">NativeAOT</a>。</p></blockquote>',25)])])}const u=a(d,[["render",c]]);export{m as __pageData,u as default};
